"""Tests for the spring course intake and lookups.

Run: python3 project/test_service.py
"""
import io
import json
import os
import re
import shutil
import sqlite3
import subprocess
import sys
import tempfile
import unittest
from contextlib import redirect_stdout
from datetime import datetime
from zoneinfo import ZoneInfo

import service

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
INPUT = os.path.join(ROOT, "input")
SERVICE_TABLES = ("service_class", "service_account", "service_day", "service_row",
                  "service_history", "service_import")
EXPECTED = {
    "A": {"Q29": "14:05", "N84": None},
    "B": {"Q29": "15:10", "N84": None},
    "C": {"Q29": "16:15", "N84": None},
    "D": {"Q29": "17:20", "N84": None},
}


def seeded():
    path = os.path.join(tempfile.mkdtemp(), "portal.sqlite")
    shutil.copyfile(os.path.join(ROOT, "data", "portal.sqlite"), path)
    return path, service.ensure(sqlite3.connect(path))


def read(path):
    with open(path, encoding="utf-8") as handle:
        return json.load(handle)


def arrival(version=2, schedule=None, roster=None, annex=None, annex41=None, clock="2026-03-30"):
    """A copy of the delivered spring folder, with the pieces a test wants to bend."""
    directory = tempfile.mkdtemp()
    for week in ("week-41", "week-42"):
        os.makedirs(os.path.join(directory, "regional", "2025", week), exist_ok=True)
    for week, replacement in (("week-41", annex41), ("week-42", annex)):
        source = os.path.join(INPUT, "regional", "2025", week, "renewal.json")
        target = os.path.join(directory, "regional", "2025", week, "renewal.json")
        if replacement is not None:
            with open(target, "w", encoding="utf-8") as handle:
                json.dump(replacement, handle)
        else:
            shutil.copyfile(source, target)
    for name, content in (("schedule.json", schedule if schedule is not None
                           else read(os.path.join(INPUT, "schedule.json"))),
                          ("roster.json", roster if roster is not None
                           else read(os.path.join(INPUT, "roster.json")))):
        with open(os.path.join(directory, name), "w", encoding="utf-8") as handle:
            json.dump(content, handle)
    with open(os.path.join(directory, "version.txt"), "w", encoding="utf-8") as handle:
        handle.write(str(version))
    with open(os.path.join(directory, "clock.txt"), "w", encoding="utf-8") as handle:
        handle.write(clock)
    return directory


def run_import(db, directory):
    out = io.StringIO()
    with redirect_stdout(out):
        code = service.do_import(db, directory)
    return code, out.getvalue()


def rows_of(db, account, asof=None):
    return service.rows_as_of(db, account, service.as_version(db, asof))


def dump(path):
    db = sqlite3.connect(path)
    try:
        return {table: sorted(db.execute(f"select * from {table}").fetchall(),
                              key=lambda row: tuple("" if value is None else str(value) for value in row))
                for table in SERVICE_TABLES + ("events", "bookings", "series")}
    finally:
        db.close()


def ics_events(text):
    return [dict(line.split(":", 1) for line in body.strip().split("\r\n"))
            for body in re.findall(r"BEGIN:VEVENT\r\n(.*?)END:VEVENT\r\n", text, re.S)]


class Intake(unittest.TestCase):
    def setUp(self):
        self.path, self.db = seeded()
        self.dir = arrival()
        run_import(self.db, self.dir)

    def tearDown(self):
        self.db.close()

    def test_every_registration_and_day_is_registered(self):
        self.assertEqual(self.db.execute("select count(*) from service_row").fetchone()[0], 16)
        for account in ("A", "B", "C", "D"):
            rows = rows_of(self.db, account)
            self.assertEqual([(r["code"], r["day"]) for r in rows],
                             [("Q29", "2026-03-02"), ("N84", "2026-03-02"),
"}

